import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"井","description":"周易集解 - 井","frontmatter":{"title":"井","description":"周易集解 - 井"},"headers":[],"relativePath":"classics/jijie/048.md","filePath":"classics/jijie/048.md"}'),l={name:"classics/jijie/048.md"};function n(p,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="井" tabindex="-1">井 <a class="header-anchor" href="#井" aria-label="Permalink to “井”">​</a></h1><h2 id="井-1" tabindex="-1">井 <a class="header-anchor" href="#井-1" aria-label="Permalink to “井”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>井，改邑不改井，無喪無得，往來井井。汔至，亦未繘井，羸其瓶，兇。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：困於上必反下*，故受之以井。</p><p>崔憬曰：困極於劓刖，則反下以求安，故言｢困乎上必反下｣也。</p><p>鄭玄曰：坎，水也。巽，木，桔槔也。互體離兌，離外堅中虛，瓶也；兌為暗澤，泉口也。言桔槔引瓶，下入泉口，汲水而出，井之象也。井以汲人，水無空竭，猶人君以政教養天下，惠澤無窮也。</p><p>虞翻曰：泰初之五也。坤為邑，乾初之五折坤。故改邑。初為舊井，四應甃之，故不改井。</p><p>虞翻曰：無喪，泰初之五。坤象毀壞，故無喪。五來之初，失位無應，故無得。坎為通，故往來井井。往謂之五，來謂之初也。</p><p>虞翻曰：巽繩，為繘。汔，幾也，謂二也。幾至初改，未繘井，未有功也。</p><p>虞翻曰：羸，鈎羅也。艮為手，巽為繘，離為瓶，手繘折其中，故羸其瓶。體兌毀缺，瓶缺漏，故兇矣。</p><p>乾寶曰：水，殷德也。木，周德也，夫井，德之地也。所以養民性命而清潔之主者也。自震化行，至於五世，改殷紂比屋之亂俗，而不易成湯昭假之法度也。故曰改邑不改井。二代之制，各因時宜，損益雖異，括囊則同，故曰｢無喪無得，往來井井｣也。當殷之末，井道之窮，故曰汔至。周德雖興，未及革正，故曰亦未繘井。井泥為穢，百姓無聊，比者之間，交受塗炭，故曰羸其瓶兇矣。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：巽乎水而上水，井。井養而不窮也。改邑不改井，乃以剛中也。無喪無得。往來井井，汔至亦未繘井，未有功也。羸其瓶，是以兇也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>荀爽曰：巽乎水，謂陰下為巽也。而上水，謂陽上為坎也。木入水出，井之象也。</p><p>虞翻曰：兌口飲水，坎為通，往來井井，故養不窮也。</p><p>荀爽曰：剛得中，故為改邑。柔不得中，故為不改井也。</p><p>荀爽曰：陰來居初，有實，為無喪。失中，為無得也。</p><p>荀爽曰：此本泰卦。陽往居五，得坎為井；陰來在下，亦為井，故曰往來井井也。</p><p>荀爽曰：汔至者，陰來居初，下至。汔，竟也。繘者，所以出水通井道也。今乃在初，未得應五，故未繘也。繘者，綆汲之具也。</p><p>虞翻曰：謂二未變應五，故未有功也。</p><p>荀爽曰：井，謂二。瓶，謂初。初欲應五，今為二所拘羸，故兇也。</p><p>孔穎達曰：計覆一瓶之水，何足言兇？但此喻人德行不恆，不能善始令終，故就人言之兇也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：木上有水，井。君子以勞民勸相。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>王弼曰：木上有水，上水之象也。水以養而不窮也。</p><p>虞翻曰：君子謂泰乾也。坤為民；初上成坎，為勸，故勞民勸相。相，相助也。謂以陽助坤矣。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，井泥不食，舊井無禽。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>乾寶曰：在井之下體，本土爻，故曰泥也。井而為泥，則不可食，故曰不食。此託紂之穢政不可以養民也。舊井，謂殷之未喪師也。亦皆清潔，無水禽之穢，又況泥土乎！故舊井無禽矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：井泥不食，下也。舊井無禽，時舍也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：食，用也。初下稱泥。巽為木果，無噬嗑食象。下而多泥，故不食也。乾為舊，位在陰下，故｢舊井無禽，時舍也｣。謂時舍於初，非其位也。與乾二同義。</p><p>崔憬曰：處井之下，無應於上。則是所用之井不汲，以其多塗久廢之井，不獲以其時舍。故曰｢井泥不食，舊井無禽｣。禽，古擒字，禽，猶獲也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，井谷射鮒，甕敝漏。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：巽為谷，為鮒。鮒，小鮮也。離為甕。甕瓶毀缺，羸其瓶兇，故甕敝漏也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：井谷射鮒，無與也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>崔憬曰：唯得於鮒，無與於人也。井之為道，上汲者也。今與五非應，與初比，則是若谷水不註，唯及於魚，故曰井谷射鮒也。甕敝漏者，取其水下註，不汲之義也。</p><p>案：魚，陰蟲也。初處井下體，又陰爻，魚之象也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，井渫不食，為我心惻。可用汲，王明，並受其福。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>荀爽曰：渫去穢濁，清潔之意也，三者得正，故曰井渫。不得據陰，喻不得用，故曰不食。道既不行，故我心惻。</p><p>荀爽曰：謂五可用汲三，則王道明而天下並受其福。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：井渫不食，行惻也。求王明，受福也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>乾寶曰：此託殷之公侯。時有賢者，獨守成湯之法度，而不見任，謂微箕之倫也。故曰｢井渫不食，為我心惻｣。惻，傷悼也。民乃外附，故曰可用汲。周德來被，故曰王明。王得其民，民得其主，故曰｢求王明，受福也｣。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，井甃，無咎。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>荀爽曰：坎性下降，嫌於從三。能自脩正，以甃輔五。故無咎也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：井甃無咎，修井也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：修，治也。以瓦甓壘井稱甃。坤為土。初之五成籬，離火燒土，為瓦治象。故曰｢井甃無咎，修井也｣。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，井冽，寒泉食。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：泉自下出稱井。周七月，夏之五月，陰氣在下。二已變坎，十一月為寒泉。初二已變，體噬嗑食。故｢冽寒泉食｣矣。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：寒泉之食，中正也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>崔憬曰：冽，清潔也。居中得正，而比於上。則是井渫水清，既寒且潔，汲上可食於人者也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，井收勿幕，有孚元吉。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：幕，蓋也。收，謂以轆轤收繘也。坎為車，應巽繩，為繘。故井收勿幕。有孚謂五坎。坎為孚，故元吉也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：元吉在上，大成也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：謂初二已變，成既濟定，故大成也。</p><p>乾寶曰：處井上位，在瓶之水也，故曰井收幕覆也。井以養生，政以養德，無覆水泉而不惠民，無蘊典禮而不興教，故曰井收勿幕。勿幕，則教信於民。民服教，則大化成也。</p>',82)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
